// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/external/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/orders", wrapper.ListOrders)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/orders/show/{id}", wrapper.GetOrder)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/external/orders/create/adhoc", wrapper.CreateAdhocOrder)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/external/orders/cancel", wrapper.CancelOrders)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/external/orders/create/return", wrapper.CreateReturnOrder)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/orders/processing/return", wrapper.ListReturnOrders)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/courier/courierListWithCounts", wrapper.ListCouriers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/courier/serviceability", wrapper.CheckServiceability)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/external/courier/assign/awb", wrapper.AssignAwb)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/courier/track/awb/{awb_code}", wrapper.TrackByAwb)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/courier/track/shipment/{shipment_id}", wrapper.TrackByShipment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/ndr/all", wrapper.ListNdr)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/ndr/{awb}", wrapper.GetNdr)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/external/ndr/{awb}/action", wrapper.ActOnNdr)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/external/settings/company/pickup", wrapper.ListPickups)

	return m
}

