// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Exchange API user credentials for the synthetic bearer token.
	// (POST /v1/external/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// AssignAwb Assign an AWB and courier to a shipment.
	// (POST /v1/external/courier/assign/awb)
	AssignAwb(ctx context.Context, request AssignAwbRequestObject) (AssignAwbResponseObject, error)
	// ListCouriers List courier partners enabled for the account.
	// (GET /v1/external/courier/courierListWithCounts)
	ListCouriers(ctx context.Context, request ListCouriersRequestObject) (ListCouriersResponseObject, error)
	// CheckServiceability List couriers that can carry a shipment between two pincodes.
	// (GET /v1/external/courier/serviceability)
	CheckServiceability(ctx context.Context, request CheckServiceabilityRequestObject) (CheckServiceabilityResponseObject, error)
	// TrackByAwb Track a shipment by AWB.
	// (GET /v1/external/courier/track/awb/{awb_code})
	TrackByAwb(ctx context.Context, request TrackByAwbRequestObject) (TrackByAwbResponseObject, error)
	// TrackByShipment Track a shipment by shipment id.
	// (GET /v1/external/courier/track/shipment/{shipment_id})
	TrackByShipment(ctx context.Context, request TrackByShipmentRequestObject) (TrackByShipmentResponseObject, error)
	// ListNdr List shipments in non-delivery report status.
	// (GET /v1/external/ndr/all)
	ListNdr(ctx context.Context, request ListNdrRequestObject) (ListNdrResponseObject, error)
	// GetNdr Get one NDR shipment by AWB.
	// (GET /v1/external/ndr/{awb})
	GetNdr(ctx context.Context, request GetNdrRequestObject) (GetNdrResponseObject, error)
	// ActOnNdr Record a re-attempt or RTO action on an NDR shipment.
	// (POST /v1/external/ndr/{awb}/action)
	ActOnNdr(ctx context.Context, request ActOnNdrRequestObject) (ActOnNdrResponseObject, error)
	// ListOrders List orders and their shipments.
	// (GET /v1/external/orders)
	ListOrders(ctx context.Context, request ListOrdersRequestObject) (ListOrdersResponseObject, error)
	// CancelOrders Cancel orders by id.
	// (POST /v1/external/orders/cancel)
	CancelOrders(ctx context.Context, request CancelOrdersRequestObject) (CancelOrdersResponseObject, error)
	// CreateAdhocOrder Create a custom order and its shipment.
	// (POST /v1/external/orders/create/adhoc)
	CreateAdhocOrder(ctx context.Context, request CreateAdhocOrderRequestObject) (CreateAdhocOrderResponseObject, error)
	// CreateReturnOrder Create a return for an order.
	// (POST /v1/external/orders/create/return)
	CreateReturnOrder(ctx context.Context, request CreateReturnOrderRequestObject) (CreateReturnOrderResponseObject, error)
	// ListReturnOrders List return orders.
	// (GET /v1/external/orders/processing/return)
	ListReturnOrders(ctx context.Context, request ListReturnOrdersRequestObject) (ListReturnOrdersResponseObject, error)
	// GetOrder Get one order by Shiprocket id or channel order id.
	// (GET /v1/external/orders/show/{id})
	GetOrder(ctx context.Context, request GetOrderRequestObject) (GetOrderResponseObject, error)
	// ListPickups List pickup locations.
	// (GET /v1/external/settings/company/pickup)
	ListPickups(ctx context.Context, request ListPickupsRequestObject) (ListPickupsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

